package vectordb

import (
	"context"
	"fmt"
	"strings"

	"github.com/Hanwen-Jiang/dag-code-agent/packages/embedding"
)

// LLMClient generates text from a prompt. Any chat/completion client can
// satisfy this; the RAG pipeline only depends on this minimal surface.
type LLMClient interface {
	Complete(ctx context.Context, prompt string) (string, error)
}

// Answer mode markers.
const (
	// AnswerModeLLM marks answers generated by an LLMClient.
	AnswerModeLLM = "llm"
	// AnswerModeNoLLM marks answers produced without an LLMClient: the
	// assembled augmented prompt itself is returned as the answer.
	AnswerModeNoLLM = "no_llm"
)

// Document is a unit of content to index for RAG.
type Document struct {
	ID       string
	Source   string
	Text     string
	Metadata map[string]any
}

// RAGConfig holds RAGPipeline configuration.
type RAGConfig struct {
	// Collection scopes all index/retrieve operations on the VectorDB.
	Collection string
	// TopK default number of chunks retrieved per query.
	TopK int
	// MinScore filters out retrieved chunks whose similarity score is below
	// this threshold (cosine similarity scale).
	MinScore float64
	// ChunkSize is the target chunk size in characters for document chunking.
	ChunkSize int
	// ChunkOverlap is the character overlap between consecutive chunks.
	ChunkOverlap int
	// SystemPrompt is prepended to every augmented prompt.
	SystemPrompt string
	// EmbedBatchSize bounds how many chunk texts are embedded per call.
	EmbedBatchSize int
}

// DefaultRAGConfig returns sensible defaults for a RAG pipeline.
func DefaultRAGConfig() RAGConfig {
	return RAGConfig{
		Collection:   "rag_documents",
		TopK:         5,
		MinScore:     0.35,
		ChunkSize:    1200,
		ChunkOverlap: 200,
		SystemPrompt: `You are a precise assistant answering questions using only the provided context. ` +
			`Cite the chunk number [n] for each factual claim. ` +
			`If the context does not contain the answer, say so explicitly.`,
		EmbedBatchSize: 64,
	}
}

// RAGAnswer is the structured result of a RAG query.
type RAGAnswer struct {
	// Answer is the final answer text. When Mode is AnswerModeNoLLM it is
	// the assembled augmented prompt itself.
	Answer string
	// Mode is AnswerModeLLM or AnswerModeNoLLM.
	Mode string
	// Prompt is the fully assembled augmented prompt (system + cited chunks
	// + query), useful for auditing or for manual LLM calls.
	Prompt string
	// Sources are the retrieved chunks that backed the answer.
	Sources []SearchResult
}

// RAGPipeline implements retrieval-augmented generation over a VectorDB and
// an EmbeddingService: documents are chunked and embedded on Index, and
// queries are embedded, retrieved, scored, and handed to an LLM (or returned
// as an augmented prompt when no LLM is configured).
type RAGPipeline struct {
	db  VectorDB
	emb embedding.EmbeddingService
	cfg RAGConfig
}

// NewRAGPipeline wires a RAG pipeline over the given vector DB and embedding
// service. Either db or emb may be nil only if you never call the methods
// that require them; both are required for real use.
func NewRAGPipeline(db VectorDB, emb embedding.EmbeddingService, cfg RAGConfig) *RAGPipeline {
	if cfg.TopK <= 0 {
		cfg.TopK = DefaultRAGConfig().TopK
	}
	if cfg.ChunkSize <= 0 {
		cfg.ChunkSize = DefaultRAGConfig().ChunkSize
	}
	if cfg.ChunkOverlap < 0 {
		cfg.ChunkOverlap = 0
	}
	if cfg.ChunkOverlap >= cfg.ChunkSize {
		cfg.ChunkOverlap = cfg.ChunkSize / 10
	}
	if cfg.EmbedBatchSize <= 0 {
		cfg.EmbedBatchSize = 64
	}
	if cfg.SystemPrompt == "" {
		cfg.SystemPrompt = DefaultRAGConfig().SystemPrompt
	}
	if cfg.Collection == "" {
		cfg.Collection = DefaultRAGConfig().Collection
	}
	return &RAGPipeline{db: db, emb: emb, cfg: cfg}
}

// GetVectorDB returns the underlying vector DB.
func (p *RAGPipeline) GetVectorDB() VectorDB { return p.db }

// Index chunks each document, embeds the chunks, and upserts them with the
// payload {source, chunk_index, text, document_id} plus any document metadata.
// Point IDs are deterministic ("<docID>::<chunkIndex>"), so re-indexing a
// document replaces its previous chunks.
func (p *RAGPipeline) Index(ctx context.Context, documents []Document) error {
	if p.db == nil {
		return fmt.Errorf("vectordb: rag pipeline has no vector db")
	}
	if p.emb == nil {
		return fmt.Errorf("vectordb: rag pipeline has no embedding service")
	}

	var points []VectorPoint
	var texts []string

	for di, doc := range documents {
		chunks := chunkText(doc.Text, p.cfg.ChunkSize, p.cfg.ChunkOverlap)
		for ci, chunk := range chunks {
			payload := map[string]any{
				"source":      doc.Source,
				"chunk_index": ci,
				"text":        chunk,
				"document_id": doc.ID,
			}
			for k, v := range doc.Metadata {
				if _, exists := payload[k]; !exists {
					payload[k] = v
				}
			}
			id := fmt.Sprintf("doc-%d-chunk-%d", di, ci)
			if doc.ID != "" {
				id = doc.ID + "::" + fmt.Sprint(ci)
			}
			points = append(points, VectorPoint{ID: id, Payload: payload})
			texts = append(texts, chunk)
		}
	}
	if len(texts) == 0 {
		return nil
	}

	// Embed in bounded batches.
	vectors := make([][]float32, 0, len(texts))
	for start := 0; start < len(texts); start += p.cfg.EmbedBatchSize {
		end := start + p.cfg.EmbedBatchSize
		if end > len(texts) {
			end = len(texts)
		}
		vecs, err := p.emb.Embed(ctx, texts[start:end])
		if err != nil {
			return fmt.Errorf("vectordb: rag index embed batch [%d:%d): %w", start, end, err)
		}
		if len(vecs) != end-start {
			return fmt.Errorf("vectordb: rag index expected %d vectors, got %d", end-start, len(vecs))
		}
		vectors = append(vectors, vecs...)
	}
	for i := range points {
		points[i].Vector = vectors[i]
	}

	// Upsert in batches.
	const upsertBatch = 200
	for start := 0; start < len(points); start += upsertBatch {
		end := start + upsertBatch
		if end > len(points) {
			end = len(points)
		}
		if err := p.db.Upsert(ctx, points[start:end]); err != nil {
			return fmt.Errorf("vectordb: rag index upsert batch [%d:%d): %w", start, end, err)
		}
	}
	return nil
}

// Retrieve embeds the query, searches the vector DB, and drops results below
// MinScore. topK <= 0 uses the configured TopK.
func (p *RAGPipeline) Retrieve(ctx context.Context, query string, topK int, filter map[string]any) ([]SearchResult, error) {
	if p.db == nil {
		return nil, fmt.Errorf("vectordb: rag pipeline has no vector db")
	}
	if p.emb == nil {
		return nil, fmt.Errorf("vectordb: rag pipeline has no embedding service")
	}
	if strings.TrimSpace(query) == "" {
		return nil, fmt.Errorf("vectordb: rag query is empty")
	}
	if topK <= 0 {
		topK = p.cfg.TopK
	}

	vecs, err := p.emb.Embed(ctx, []string{query})
	if err != nil {
		return nil, fmt.Errorf("vectordb: rag query embed: %w", err)
	}

	results, err := p.db.Query(ctx, QueryRequest{
		Collection:    p.cfg.Collection,
		Vector:        vecs[0],
		TopK:          topK,
		FilterPayload: filter,
	})
	if err != nil {
		return nil, fmt.Errorf("vectordb: rag retrieve: %w", err)
	}

	if p.cfg.MinScore <= 0 {
		return results, nil
	}
	kept := make([]SearchResult, 0, len(results))
	for _, r := range results {
		if r.Score >= p.cfg.MinScore {
			kept = append(kept, r)
		}
	}
	return kept, nil
}

// Query retrieves relevant chunks, builds the augmented prompt, and generates
// the answer via llm. If llm is nil the assembled augmented prompt is
// returned as the answer and the pipeline marks it with the "no_llm" mode.
// Use QueryWithAnswer to inspect the mode/prompt/sources struct directly.
func (p *RAGPipeline) Query(ctx context.Context, query string, llm LLMClient) (string, error) {
	ans, err := p.QueryWithAnswer(ctx, query, llm)
	if err != nil {
		return "", err
	}
	return ans.Answer, nil
}

// QueryWithAnswer is Query plus structured result exposure (mode, prompt,
// and the cited sources).
func (p *RAGPipeline) QueryWithAnswer(ctx context.Context, query string, llm LLMClient) (*RAGAnswer, error) {
	results, err := p.Retrieve(ctx, query, p.cfg.TopK, nil)
	if err != nil {
		return nil, err
	}
	prompt := p.buildPrompt(query, results)

	if llm == nil {
		return &RAGAnswer{
			Answer:  prompt,
			Mode:    AnswerModeNoLLM,
			Prompt:  prompt,
			Sources: results,
		}, nil
	}

	answer, err := llm.Complete(ctx, prompt)
	if err != nil {
		return nil, fmt.Errorf("vectordb: rag llm complete: %w", err)
	}
	return &RAGAnswer{
		Answer:  answer,
		Mode:    AnswerModeLLM,
		Prompt:  prompt,
		Sources: results,
	}, nil
}

// buildPrompt assembles the augmented prompt: system prompt, the cited
// retrieved chunks, and the user query.
func (p *RAGPipeline) buildPrompt(query string, results []SearchResult) string {
	var b strings.Builder
	b.WriteString(p.cfg.SystemPrompt)
	b.WriteString("\n\nContext chunks retrieved for the question:\n")
	if len(results) == 0 {
		b.WriteString("(no relevant chunks found)\n")
	}
	for i, r := range results {
		source := r.Payload["source"]
		chunkIdx := r.Payload["chunk_index"]
		text := r.Payload["text"]
		b.WriteString(fmt.Sprintf("\n[%d] (source=%v, chunk=%v, score=%.4f)\n%s\n",
			i+1, source, chunkIdx, r.Score, text))
	}
	b.WriteString("\nQuestion: ")
	b.WriteString(query)
	b.WriteString("\n\nAnswer:")
	return b.String()
}

// chunkText splits text into overlapping chunks of roughly size characters,
// preferring whitespace boundaries. It is deterministic and never returns
// overlapping-duplicate runaway sequences: each chunk advances at least one
// character.
func chunkText(text string, size, overlap int) []string {
	text = strings.TrimSpace(text)
	if text == "" {
		return nil
	}
	if size <= 0 {
		size = 1200
	}
	if overlap < 0 || overlap >= size {
		overlap = size / 10
	}

	var chunks []string
	start := 0
	for start < len(text) {
		end := start + size
		if end >= len(text) {
			chunks = append(chunks, text[start:])
			break
		}
		// Prefer a whitespace boundary within the last 20% of the window so
		// words are not split mid-token.
		cut := -1
		lo := start + size*8/10
		for i := end - 1; i >= lo; i-- {
			if text[i] == ' ' || text[i] == '\n' || text[i] == '\t' || text[i] == '\r' {
				cut = i
				break
			}
		}
		if cut > start {
			end = cut
		}
		if chunk := strings.TrimSpace(text[start:end]); chunk != "" {
			chunks = append(chunks, chunk)
		}
		next := end - overlap
		if next <= start {
			next = end
		}
		start = next
	}
	return chunks
}
